/**
 * 某日的方位、百忌、胎神全集。
 */
function positionOf(y, m, d) {
  const gzIdx = dayGanZhiIndex(y, m, d);
  const gan = GAN[gzIdx % 10].z;
  const zhi = ZHI[gzIdx % 12].z;
  return {
    方位: { 喜神: XISHEN[gzIdx % 10], 财神: CAISHEN[gzIdx % 10], 福神: FUSHEN[gzIdx % 10], 阳贵: YANGGUI[gzIdx % 10], 阴贵: YINGUI[gzIdx % 10] },
    彭祖百忌: { 干: PENGZU_GAN[gan], 支: PENGZU_ZHI[zhi] },
    胎神: TAISHEN[JIAZI[gzIdx]] || '',
  };
}


module.exports.positionOf = positionOf;
module.exports.PENGZU_GAN = PENGZU_GAN;
module.exports.PENGZU_ZHI = PENGZU_ZHI;
